// A replacement operator new has a fixed signature, so the counter cannot be an argument.
std::int64_t allocation_count = 0;

void* operator new(std::size_t bytes) {
  ++allocation_count;
  if (void* memory = std::malloc(bytes)) return memory;
  throw std::bad_alloc{};
}
void operator delete(void* memory) noexcept { std::free(memory); }
void operator delete(void* memory, std::size_t) noexcept { std::free(memory); }

// ---- the planners, as plain settings structs that derive from nothing ----

struct PurePursuit {
  std::int32_t top_speed_mm_s;
  std::int32_t lookahead_mm;
};
struct Stanley {
  std::int32_t top_speed_mm_s;
  std::int32_t lookahead_mm;
};
struct Hold {
  std::int32_t speed_mm_s;
};

[[nodiscard]] constexpr std::int32_t speed_of(PurePursuit p, std::int32_t to_goal_mm) {
  return to_goal_mm >= p.lookahead_mm ? p.top_speed_mm_s : p.top_speed_mm_s * to_goal_mm / p.lookahead_mm;
}
[[nodiscard]] constexpr std::int32_t speed_of(Stanley p, std::int32_t to_goal_mm) {
  return p.top_speed_mm_s * to_goal_mm / (to_goal_mm + p.lookahead_mm);
}
[[nodiscard]] constexpr std::int32_t speed_of(Hold p, std::int32_t) { return p.speed_mm_s; }

[[nodiscard]] constexpr std::string_view name_of(PurePursuit) { return "pure_pursuit"; }
[[nodiscard]] constexpr std::string_view name_of(Stanley) { return "stanley"; }
[[nodiscard]] constexpr std::string_view name_of(Hold) { return "hold"; }

// ---- reading the parameters: a step that can fail, and says why ----

enum class PlannerKind { pure_pursuit, stanley, hold };
enum class ConfigError { unknown_kind, speed_out_of_range, lookahead_out_of_range };

struct PlannerParams {  // what a node reads from its parameter file
  std::string kind;
  std::int32_t top_speed_mm_s;
  std::int32_t lookahead_mm;
};

struct PlannerConfig {  // the same values, checked
  PlannerKind kind;
  std::int32_t top_speed_mm_s;
  std::int32_t lookahead_mm;
};

[[nodiscard]] std::optional<PlannerKind> kind_from(std::string_view name) {
  if (name == "pure_pursuit") return PlannerKind::pure_pursuit;
  if (name == "stanley") return PlannerKind::stanley;
  if (name == "hold") return PlannerKind::hold;
  return std::nullopt;
}

[[nodiscard]] constexpr std::string_view text_of(ConfigError error) {
  switch (error) {
    case ConfigError::unknown_kind:
      return "planner.kind is not one of pure_pursuit, stanley, hold";
    case ConfigError::speed_out_of_range:
      return "planner.top_speed_mm_s must be in [1, 2000]";
    case ConfigError::lookahead_out_of_range:
      return "planner.lookahead_mm must be in [100, 5000]";
  }
  return "unknown error";
}

// C++23 spells this std::expected<PlannerConfig, ConfigError>.
[[nodiscard]] std::variant<PlannerConfig, ConfigError> read_config(const PlannerParams& params) {
  const std::optional<PlannerKind> kind = kind_from(params.kind);
  if (!kind) return ConfigError::unknown_kind;
  if (params.top_speed_mm_s < 1 || params.top_speed_mm_s > 2000) return ConfigError::speed_out_of_range;
  if (params.lookahead_mm < 100 || params.lookahead_mm > 5000) return ConfigError::lookahead_out_of_range;
  return PlannerConfig{.kind = *kind, .top_speed_mm_s = params.top_speed_mm_s, .lookahead_mm = params.lookahead_mm};
}

// ---- creating the planner: a step that cannot fail, because the config is already valid ----

class Planner {
 public:
  Planner() = default;
  Planner(const Planner&) = delete;
  Planner& operator=(const Planner&) = delete;
  virtual ~Planner() = default;
  [[nodiscard]] virtual std::string_view name() const = 0;
  [[nodiscard]] virtual std::int32_t speed_mm_s(std::int32_t to_goal_mm) const = 0;
};

template <typename Settings>
class PlannerModel final : public Planner {
 public:
  explicit PlannerModel(Settings settings) : settings_(settings) {}
  [[nodiscard]] std::string_view name() const override { return name_of(settings_); }
  [[nodiscard]] std::int32_t speed_mm_s(std::int32_t to_goal_mm) const override {
    return speed_of(settings_, to_goal_mm);
  }

 private:
  Settings settings_;
};

[[nodiscard]] std::unique_ptr<Planner> make_planner(const PlannerConfig& config) {
  switch (config.kind) {
    case PlannerKind::pure_pursuit:
      return std::make_unique<PlannerModel<PurePursuit>>(
          PurePursuit{.top_speed_mm_s = config.top_speed_mm_s, .lookahead_mm = config.lookahead_mm});
    case PlannerKind::stanley:
      return std::make_unique<PlannerModel<Stanley>>(
          Stanley{.top_speed_mm_s = config.top_speed_mm_s, .lookahead_mm = config.lookahead_mm});
    case PlannerKind::hold:
      return std::make_unique<PlannerModel<Hold>>(Hold{.speed_mm_s = config.top_speed_mm_s});
  }
  return std::make_unique<PlannerModel<Hold>>(Hold{.speed_mm_s = 0});
}

// The same factory over a closed set, returning a value instead of a pointer.
using AnyPlanner = std::variant<PurePursuit, Stanley, Hold>;

template <typename... Fs>
struct overloaded : Fs... {
  using Fs::operator()...;
};

[[nodiscard]] AnyPlanner make_planner_value(const PlannerConfig& config) {
  switch (config.kind) {
    case PlannerKind::pure_pursuit:
      return PurePursuit{.top_speed_mm_s = config.top_speed_mm_s, .lookahead_mm = config.lookahead_mm};
    case PlannerKind::stanley:
      return Stanley{.top_speed_mm_s = config.top_speed_mm_s, .lookahead_mm = config.lookahead_mm};
    case PlannerKind::hold:
      return Hold{.speed_mm_s = config.top_speed_mm_s};
  }
  return Hold{.speed_mm_s = 0};
}

[[nodiscard]] std::string described(const AnyPlanner& planner, std::int32_t to_goal_mm) {
  return std::visit([to_goal_mm](const auto& p) { return std::format("{} {}", name_of(p), speed_of(p, to_goal_mm)); },
                    planner);
}

int main() {
  const std::vector<PlannerParams> files{
      {.kind = "pure_pursuit", .top_speed_mm_s = 1200, .lookahead_mm = 800},
      {.kind = "stanley", .top_speed_mm_s = 1200, .lookahead_mm = 800},
      {.kind = "hold", .top_speed_mm_s = 300, .lookahead_mm = 800},
      {.kind = "dwb", .top_speed_mm_s = 1200, .lookahead_mm = 800},
      {.kind = "stanley", .top_speed_mm_s = 9000, .lookahead_mm = 800},
  };

  std::vector<PlannerConfig> good;
  for (const PlannerParams& params : files) {
    const std::variant<PlannerConfig, ConfigError> result = read_config(params);
    std::visit(overloaded{
                   [&](const PlannerConfig& config) {
                     good.push_back(config);
                     std::cout << std::format("{:<13} accepted\n", params.kind);
                   },
                   [&](ConfigError error) {
                     std::cout << std::format("{:<13} rejected: {}\n", params.kind, text_of(error));
                   },
               },
               result);
  }

  // Both vectors reserve their buffer first, so the counts below are the planners and nothing else.
  std::vector<std::unique_ptr<Planner>> planners;
  planners.reserve(good.size());
  std::vector<AnyPlanner> values;
  values.reserve(good.size());

  const std::int64_t before_pointers = allocation_count;
  for (const PlannerConfig& config : good) planners.push_back(make_planner(config));
  const std::int64_t pointer_allocations = allocation_count - before_pointers;

  const std::int64_t before_values = allocation_count;
  for (const PlannerConfig& config : good) values.push_back(make_planner_value(config));
  const std::int64_t value_allocations = allocation_count - before_values;

  std::cout << "planner       400 mm out  3000 mm out\n";
  for (const std::unique_ptr<Planner>& planner : planners) {
    std::cout << std::format("{:<13} {:>10}  {:>11}\n", planner->name(), planner->speed_mm_s(400),
                             planner->speed_mm_s(3000));
  }

  std::cout << std::format(
      "the three values agree: {}\n",
      described(values.front(), 400) ==
          std::format("{} {}", planners.front()->name(), planners.front()->speed_mm_s(400)));
  std::cout << std::format("allocations for {} planners behind unique_ptr: {}\n", good.size(), pointer_allocations);
  std::cout << std::format("allocations for {} planners as a variant:      {}\n", good.size(), value_allocations);
  std::cout << std::format("sizeof: unique_ptr<Planner> {}, AnyPlanner {}\n", sizeof(std::unique_ptr<Planner>),
                           sizeof(AnyPlanner));
}

