struct Report {
  std::string controller;
  std::int64_t samples;
  std::int64_t total_abs_steer_mdeg;
};

[[nodiscard]] std::string shown(const Report& report) {
  return std::format("{:<13} {:>3} samples, {:>6} mdeg of steering", report.controller, report.samples,
                     report.total_abs_steer_mdeg);
}

class Controller {
 public:
  Controller() = default;
  Controller(const Controller&) = delete;
  Controller& operator=(const Controller&) = delete;
  virtual ~Controller() = default;
  [[nodiscard]] virtual std::string_view name() const = 0;
  [[nodiscard]] virtual std::int32_t steer_mdeg(std::int32_t offset_mm) const = 0;
};

class Proportional final : public Controller {
 public:
  Proportional(std::string_view name, std::int32_t gain_mdeg_per_mm) : name_(name), gain_(gain_mdeg_per_mm) {}
  [[nodiscard]] std::string_view name() const override { return name_; }
  [[nodiscard]] std::int32_t steer_mdeg(std::int32_t offset_mm) const override { return offset_mm * gain_; }

 private:
  std::string name_;
  std::int32_t gain_;
};

class Deadband final : public Controller {
 public:
  Deadband(std::int32_t tolerance_mm, std::int32_t gain_mdeg_per_mm)
      : tolerance_(tolerance_mm), gain_(gain_mdeg_per_mm) {}
  [[nodiscard]] std::string_view name() const override { return "slalom"; }
  [[nodiscard]] std::int32_t steer_mdeg(std::int32_t offset_mm) const override {
    return offset_mm > -tolerance_ && offset_mm < tolerance_ ? 0 : offset_mm * gain_;
  }

 private:
  std::int32_t tolerance_;
  std::int32_t gain_;
};

// ---- 1. Factory Method: the base owns the workflow, the subclass owns the creation step ----

class Scenario {
 public:
  Scenario() = default;
  Scenario(const Scenario&) = delete;
  Scenario& operator=(const Scenario&) = delete;
  virtual ~Scenario() = default;

  [[nodiscard]] Report run(std::span<const std::int32_t> offsets_mm) const {
    const std::unique_ptr<Controller> controller = make_controller();  // the step subclasses override
    std::int64_t total = 0;
    for (const std::int32_t offset_mm : offsets_mm) total += std::abs(controller->steer_mdeg(offset_mm));
    return Report{.controller = std::string(controller->name()),
                  .samples = std::ssize(offsets_mm),
                  .total_abs_steer_mdeg = total};
  }

 protected:
  [[nodiscard]] virtual std::unique_ptr<Controller> make_controller() const = 0;
};

class GentleRun final : public Scenario {
 protected:
  [[nodiscard]] std::unique_ptr<Controller> make_controller() const override {
    return std::make_unique<Proportional>("gentle", 8);
  }
};

class SharpRun final : public Scenario {
 protected:
  [[nodiscard]] std::unique_ptr<Controller> make_controller() const override {
    return std::make_unique<Proportional>("sharp", 20);
  }
};

class SlalomRun final : public Scenario {
 protected:
  [[nodiscard]] std::unique_ptr<Controller> make_controller() const override {
    return std::make_unique<Deadband>(30, 12);
  }
};

// ---- 2. A simple factory function, and one workflow class that takes what it makes ----

enum class ControllerKind { gentle, sharp, slalom };

[[nodiscard]] std::optional<ControllerKind> kind_from(std::string_view name) {
  if (name == "gentle") return ControllerKind::gentle;
  if (name == "sharp") return ControllerKind::sharp;
  if (name == "slalom") return ControllerKind::slalom;
  return std::nullopt;
}

[[nodiscard]] std::unique_ptr<Controller> make_controller(ControllerKind kind) {
  switch (kind) {
    case ControllerKind::gentle:
      return std::make_unique<Proportional>("gentle", 8);
    case ControllerKind::sharp:
      return std::make_unique<Proportional>("sharp", 20);
    case ControllerKind::slalom:
      return std::make_unique<Deadband>(30, 12);
  }
  return std::make_unique<Proportional>("gentle", 8);
}

class Run {
 public:
  explicit Run(std::unique_ptr<Controller> controller) : controller_(std::move(controller)) {}

  [[nodiscard]] Report run(std::span<const std::int32_t> offsets_mm) const {
    std::int64_t total = 0;
    for (const std::int32_t offset_mm : offsets_mm) total += std::abs(controller_->steer_mdeg(offset_mm));
    return Report{.controller = std::string(controller_->name()),
                  .samples = std::ssize(offsets_mm),
                  .total_abs_steer_mdeg = total};
  }

 private:
  std::unique_ptr<Controller> controller_;
};

// Both count the same two hierarchies: the Scenario side and the Controller side.
[[nodiscard]] constexpr std::int32_t classes_with_factory_method(std::int32_t workflows, std::int32_t controllers) {
  // one Scenario subclass per pair, the Scenario base, the Controller interface, one class per controller
  return workflows * controllers + 1 + 1 + controllers;
}
[[nodiscard]] constexpr std::int32_t classes_with_factory_function(std::int32_t workflows, std::int32_t controllers) {
  // one class per workflow, the Controller interface, one class per controller
  return workflows + 1 + controllers;
}

int main() {
  const std::vector<std::int32_t> offsets_mm{5, -40, 120, -15, 0, 60};

  std::vector<std::unique_ptr<Scenario>> scenarios;
  scenarios.push_back(std::make_unique<GentleRun>());
  scenarios.push_back(std::make_unique<SharpRun>());
  scenarios.push_back(std::make_unique<SlalomRun>());

  std::cout << "factory method\n";
  for (const std::unique_ptr<Scenario>& scenario : scenarios) {
    std::cout << std::format("  {}\n", shown(scenario->run(offsets_mm)));
  }

  std::cout << "factory function\n";
  for (const std::string_view wanted : {"gentle", "sharp", "slalom", "dwb"}) {
    const std::optional<ControllerKind> kind = kind_from(wanted);
    if (!kind) {
      std::cout << std::format("  {:<13} no such controller\n", wanted);
      continue;
    }
    const Run run(make_controller(*kind));
    std::cout << std::format("  {}\n", shown(run.run(offsets_mm)));
  }

  std::cout << std::format(
      "3 workflows and 4 controllers: {} classes with Factory Method, {} with a factory function\n",
      classes_with_factory_method(3, 4), classes_with_factory_function(3, 4));
}

#include <cstdint>
#include <format>
#include <iostream>
#include <memory>
#include <string_view>
#include <utility>

class Controller {
 public:
  Controller() = default;
  Controller(const Controller&) = delete;
  Controller& operator=(const Controller&) = delete;
  virtual ~Controller() = default;
  [[nodiscard]] virtual std::string_view name() const = 0;
};

class Proportional final : public Controller {
 public:
  [[nodiscard]] std::string_view name() const override { return "proportional"; }
};

class Deadband final : public Controller {
 public:
  [[nodiscard]] std::string_view name() const override { return "deadband"; }
};

class Scenario {
 public:
  Scenario() : controller_(make_controller()) {}  // a virtual call from a constructor: this is the bug
  Scenario(const Scenario&) = delete;
  Scenario& operator=(const Scenario&) = delete;
  virtual ~Scenario() = default;
  [[nodiscard]] std::string_view controller_name() const { return controller_->name(); }

 protected:
  [[nodiscard]] virtual std::unique_ptr<Controller> make_controller() const {
    return std::make_unique<Proportional>();
  }

 private:
  std::unique_ptr<Controller> controller_;
};

class SlalomRun final : public Scenario {
 protected:
  [[nodiscard]] std::unique_ptr<Controller> make_controller() const override {
    return std::make_unique<Deadband>();
  }
};

// The fix: build the controller before the object that holds it, and pass it in.
class Run {
 public:
  explicit Run(std::unique_ptr<Controller> controller) : controller_(std::move(controller)) {}
  [[nodiscard]] std::string_view controller_name() const { return controller_->name(); }

 private:
  std::unique_ptr<Controller> controller_;
};

int main() {
  const SlalomRun slalom;
  std::cout << std::format("SlalomRun asked for a deadband and got:  {}\n", slalom.controller_name());

  const Run injected(std::make_unique<Deadband>());
  std::cout << std::format("Run was handed one and got:              {}\n", injected.controller_name());
}

#include <format>
#include <functional>
#include <iostream>
#include <map>
#include <memory>
#include <optional>
#include <string>
#include <string_view>
#include <utility>

class Controller {
 public:
  Controller() = default;
  Controller(const Controller&) = delete;
  Controller& operator=(const Controller&) = delete;
  virtual ~Controller() = default;
  [[nodiscard]] virtual std::string_view name() const = 0;
};

class Named final : public Controller {
 public:
  explicit Named(std::string_view name) : name_(name) {}
  [[nodiscard]] std::string_view name() const override { return name_; }

 private:
  std::string name_;
};

using Creator = std::function<std::unique_ptr<Controller>()>;

// One map, shared by the whole process, reached through initialisation on first use.
// This is the construct the section is about, not a shape to copy.
[[nodiscard]] std::map<std::string, Creator, std::less<>>& registry() {
  static std::map<std::string, Creator, std::less<>> creators;
  return creators;
}

void register_controller(std::string name, Creator creator) {
  registry().insert_or_assign(std::move(name), std::move(creator));
}

[[nodiscard]] std::optional<std::unique_ptr<Controller>> create(std::string_view name) {
  const auto found = registry().find(name);
  if (found == registry().end()) return std::nullopt;
  return found->second();
}

[[nodiscard]] std::string built(std::string_view name) {
  const std::optional<std::unique_ptr<Controller>> controller = create(name);
  return controller ? std::string((*controller)->name()) : std::string("nothing registered");
}

int main() {
  register_controller("lane", [] { return std::make_unique<Named>("lane_follower"); });
  std::cout << std::format("production build:      {}\n", built("lane"));

  // One test wants a stub, and registers one under the same name.
  register_controller("lane", [] { return std::make_unique<Named>("stub"); });
  std::cout << std::format("inside that one test:  {}\n", built("lane"));

  // The next test never touched the registry.
  std::cout << std::format("the next test:         {}\n", built("lane"));
  std::cout << std::format("a name nobody added:   {}\n", built("dwb"));
}
